import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Locked images and videos, generated by `scripts/build-private.ts` into `private/`.
 * The folder is bundled only into the server function (never into static output) and served by
 * the gated `/protected/*` endpoints.
 */
export const PRIVATE_DIR = "private";
export const IMAGE_FORMATS = ["avif", "webp"] as const;

export interface PrivateManifest {
  images: Record<string, { width: number; height: number; widths: number[] }>;
  /** Video files in `private/media/`, by file name. */
  media: Record<string, { size: number }>;
}

let cached: PrivateManifest | undefined;

/** Reads the manifest from the working directory (the function root on Vercel). */
export function privateManifest(): PrivateManifest {
  if (cached) return cached;
  try {
    cached = JSON.parse(
      readFileSync(join(process.cwd(), PRIVATE_DIR, "manifest.json"), "utf8"),
    ) as PrivateManifest;
  } catch {
    cached = { images: {}, media: {} };
  }
  return cached;
}

export function privateFilePath(...parts: string[]): string {
  return join(process.cwd(), PRIVATE_DIR, ...parts);
}

/** `<id>-<width>.<format>`, with the id format produced by `privateImageId`. */
export const PRIVATE_IMAGE_FILE = /^([a-z0-9-]+--[a-z0-9-]+-[0-9a-f]{10})-(\d{2,4})\.(avif|webp)$/;
/** `<id>.<ext>` for locked videos, see `privateMediaFile`. */
export const PRIVATE_MEDIA_FILE = /^[a-z0-9-]+--[a-z0-9-]+-[0-9a-f]{10}\.(mp4|webm)$/;

/** Largest slice served per request, below Vercel's 4.5 MB function response limit. */
export const MEDIA_CHUNK_BYTES = 2 * 1024 * 1024;

/**
 * Byte range to serve for a `Range` header. Open-ended and oversized ranges are capped to
 * `chunk`; browsers then request the next slice. Returns undefined for unsatisfiable ranges.
 */
export function mediaRange(
  header: string | null,
  size: number,
  chunk = MEDIA_CHUNK_BYTES,
): { start: number; end: number; partial: boolean } | undefined {
  if (!header) return { start: 0, end: size - 1, partial: false };
  const match = /^bytes=(\d*)-(\d*)$/.exec(header.trim());
  if (!match || (match[1] === "" && match[2] === "")) return undefined;
  let start: number;
  let end: number;
  if (match[1] === "") {
    // Suffix range: the last N bytes.
    start = Math.max(0, size - Number(match[2]));
    end = size - 1;
  } else {
    start = Number(match[1]);
    end = match[2] === "" ? size - 1 : Math.min(Number(match[2]), size - 1);
  }
  if (start >= size || end < start) return undefined;
  return { start, end: Math.min(end, start + chunk - 1), partial: true };
}
